assignments.value:
={{
(() => {
  const p = $('CAF - Consultar producto').item.json.prod || {};
  const existenciaResp = $('CAF - Consultar existencia del producto').item.json || {};
  const registros = Array.isArray(existenciaResp.v_existencia)
    ? existenciaResp.v_existencia
    : [];

  const limpio = (v) => (v ?? '').toString().trim();

  const codigo = limpio(p.codpro);
  const producto = limpio(p.nombre_prod);
  const categoria = limpio(p.categoria);
  const fabricante = limpio(p.codigo_fabricante);
  const unidad = limpio(p.umedida);

  const precioNumerico = Number(p.precioa || 0);
  const precio = precioNumerico > 0
    ? "Q" + precioNumerico.toLocaleString("en-US", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })
    : "No registrado";

  let total = 0;

  const detalleBodegas = registros.map(r => {
    const bodega = limpio(r.bodega);
    const existencia = Number(r.existencia || 0);

    total += existencia;

    return "- 📦 Bodega " + bodega + ": " +
      existencia.toLocaleString("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
      }) +
      " unidades";
  }).join("\n");

  let respuesta =
    "Información consultada directamente en CAF Web:\n\n" +
    "**Datos del producto**\n" +
    "- Código: " + codigo + "\n" +
    "- Producto: " + producto + "\n" +
    "- Categoría: " + categoria + "\n" +
    "- Código fabricante: " + (fabricante || "No registrado") + "\n" +
    "- Unidad: " + (unidad || "No registrada") + "\n\n" +
    "**Precio**\n" +
    "- 💰 Precio A CAF: " + precio;

  if (existenciaResp.error) {
    respuesta +=
      "\n\n**Existencias**\n" +
      "- No pude consultar las existencias en CAF Web en este momento. Intenta nuevamente.";
  } else if (registros.length > 0) {
    respuesta +=
      "\n\n**Existencias por bodega**\n" +
      detalleBodegas +
      "\n\n**Existencia total: " +
      total.toLocaleString("en-US", {
        minimumFractionDigits: 0,
        maximumFractionDigits: 2
      }) +
      " unidades**";
  } else {
    respuesta +=
      "\n\n**Existencia**\n" +
      "- No se encontraron registros de existencia para este producto.";
  }

  return respuesta;
})()
}}

