  const limpiarCorreo = (v) => limpio(v).replace(/\\@/g, '@');

  const telefono = limpio(c.telefono);
  const contacto = limpio(c.contacto);

  const correo = [...new Set(
    limpiarCorreo(c.email)
      .split(',')
      .map(x => x.trim())
