    "🔹 Cliente: " + limpio(c.nombre_cliente) + "\n" +
    "🔹 NIT: " + limpio(c.nit) + "\n" +
    "🔹 Dirección: " + limpio(c.direccion) + "\n" +
    "🔹 Ciudad: " + limpio(c.ciudad) + "\n" +
    "🔹 Teléfono: " + (telefono || "No registrado") + "\n" +
    "🔹 Contacto: " + (contacto || "No registrado") + "\n" +
    "🔹 Correo: " + (correo || "No registrado");

  if (faltantes.length > 0) {
    respuesta +=
      "\n\n⚠️ Información pendiente de completar:\n" +
