  ? "No pude consultar CAF Web en este momento. Intenta nuevamente en unos segundos."
  : "No encontré movimientos para esa cuenta en la respuesta de CAF Web. Verifica la cuenta e inténtalo nuevamente."
}}

parameters.jsCode:
const input = $('Configuración CAF').item.json || {};
const mensajeOriginal = (input.chatInput || '').toString();
const mensaje = mensajeOriginal.trim();
const sessionId = (input.sessionId || input.session_id || input.webhookId || 'sesion-default').toString();
let cotizacionEstabaActiva = false;
let forzarIntencionCliente = false;
let clienteBusquedaGeneral = '';

// Estado persistente leído desde la Data Table de n8n.
let estado = null;
try {
  if ($json && $json.state_json) estado = JSON.parse($json.state_json);
} catch (e) {}

if (!estado || typeof estado !== 'object') {
  estado = {
    active: false,
    phase: 'base',
    pendingField: '',
    draft: {
      cuenta_cliente: '',
      codigo_producto: '',
      cantidad: null,
      direccion_entrega: '',
      contacto: '',
      correo: '',
      telefono: ''
    },
    commercialApproved: false
  };
}

cotizacionEstabaActiva = Boolean(estado.active);
if (!estado.draft || typeof estado.draft !== 'object') estado.draft = {};
let draft = estado.draft;

const salida = (extra = {}) => ({
  ...input,
  ...extra,
  draft,
  sessionKeyCotizacion: sessionId,
  persist_session_id: sessionId,
  persist_state_json: JSON.stringify(estado),
  forzarIntencionCliente,
  clienteBusquedaGeneral
});

const limpiar = v => (v ?? '').toString().trim();
const emailValido = v => {
  const normalizado = limpiar(v).replace(/\\@/g, '@');
  const m = normalizado.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0] : '';
};
const telefonoValido = v => {
  const m = limpiar(v).match(/\+?\d[\d\s().-]{6,}\d/);
  return m ? m[0].trim() : '';
};

let resolverClientePorNombre = false;
let clienteBusqueda = '';

// -----------------------------------------------------------------------------
// CONTEXTO CONVERSACIONAL PARA CONSULTA DE CLIENTES
// Mantiene la intención cuando el asistente pidió cuenta/nombre en el turno anterior.
// -----------------------------------------------------------------------------
if (!estado.pendingLookup) estado.pendingLookup = '';

const cuentaMensajeGeneral = (mensaje.toUpperCase().match(/\b[A-Z]{1,5}-\d{2,8}\b/) || [''])[0];
const normalCliente = mensaje
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/\s+/g,' ').trim();

const solicitudGenericaCliente =
  /\b(informacion|datos|consultar|consulta|buscar|busqueda)\b.*\bcliente\b/i.test(normalCliente) &&
  !cuentaMensajeGeneral &&
  !/\b(?:ingenio|industria|industrial|sociedad|empresa|corporacion|corporación|compania|compañia|s\.a\.|sa)\b/i.test(mensaje);

if (!estado.active && solicitudGenericaCliente) {
  estado.pendingLookup = 'cliente';
}

if (!estado.active && estado.pendingLookup === 'cliente') {
  const textoNombre = mensaje
    .replace(/^\s*(?:para|sobre|de|cliente|es|seria|sería|el cliente es|la empresa es)\s+/i,'')
    .trim();

  if (cuentaMensajeGeneral) {
    forzarIntencionCliente = true;
    estado.pendingLookup = '';
  } else if (!solicitudGenericaCliente && textoNombre.length >= 3) {
    forzarIntencionCliente = true;
    clienteBusquedaGeneral = textoNombre;
  }
}

// -----------------------------------------------------------------------------
// APROBACIÓN TÉCNICA PERSISTENTE
// -----------------------------------------------------------------------------
const aprobacionTecnica = mensaje.match(/\b(?:aprobar|apruebo|aprobado|validar|validado)\s+t[eé]cnicamente\s+([A-Z0-9-]{5,})(?:\s+por\s+(.+))?$/i);

if (aprobacionTecnica) {
  const codigo = limpiar(aprobacionTecnica[1]).toUpperCase();
  const responsable = limpiar(aprobacionTecnica[2]);

  const ctx = estado.technicalContext;
  const candidatos = Array.isArray(ctx?.candidatos) ? ctx.candidatos : [];
  const candidato = candidatos.find(c => limpiar(c.codigo).toUpperCase() === codigo);

  if (!ctx || !ctx.active || !candidato) {
    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion:
          'No encontré ese código dentro del último cruce técnico de esta sesión. Realiza primero la búsqueda técnica del producto y luego registra la aprobación.'
      })
    }];
  }

  if (!responsable) {
    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion:
          'Para dejar trazabilidad necesito el responsable técnico. Usa: **Aprobar técnicamente ' + codigo + ' por Nombre del responsable técnico**.'
      })
    }];
  }

  ctx.approved = true;
  ctx.approvedCode = codigo;
  ctx.approvedBy = responsable;
  ctx.approvedAt = new Date().toISOString();
  estado.technicalContext = ctx;

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      mensajeCotizacion:
        '✅ **Validación técnica registrada.**\n\n' +
        '- Código CAF: **' + codigo + '**\n' +
        '- Responsable: **' + responsable + '**\n' +
        '- Estado técnico previo: **' + limpiar(ctx.servicio_validado || 'PENDIENTE') + '**\n\n' +
        'La validación manual libera este código para continuar con la cotización. Indícame el cliente y la cantidad cuando quieras continuar.'
    })
  }];
}

const solicitaGenerarDocumento =
  /\b(aprobar|apruebo|aprobado|generar|genera|crear|crea|preparar|prepara|revisar|revisa)\b.*\b(cotizaci[oó]n|documento|pdf|word)\b/i.test(mensaje) ||
  /\b(pdf|word)\b.*\b(cotizaci[oó]n|documento)\b/i.test(mensaje);

// Si el usuario inicia explícitamente una cotización nueva con cliente, producto y cantidad,
// reinicia cualquier estado conversacional pendiente de una prueba anterior en la misma sesión.
const iniciaNuevaCotizacion =
  /\b(cot[ií]z[a-záéíóúñ]*|presupuesto|proforma)\b/i.test(mensaje);
const cuentaNueva = (mensaje.toUpperCase().match(/\b[A-Z]{1,5}-\d{2,8}\b/) || [null])[0];
const codigosNuevos = mensaje.toUpperCase().match(/\b(?=[A-Z0-9-]*[A-Z])(?=[A-Z0-9-]*\d)[A-Z0-9-]{5,}\b/g) || [];
const codigoNuevo = codigosNuevos.find(x => x !== cuentaNueva && !/^[A-Z]{1,5}-\d{2,8}$/.test(x));
const cantidadNuevaMatch =
  mensaje.match(/(?:quiero\s+cotizar|necesito\s+cotizar|cotizar|cantidad(?:\s+de)?|cant(?:idad)?|necesito|quiero)\s*:?\s*(\d+(?:[.,]\d+)?)/i) ||
  mensaje.match(/\b(\d+(?:[.,]\d+)?)\s*(?:unidades?|uds?|piezas?)\b/i);

if (
  iniciaNuevaCotizacion &&
  cuentaNueva &&
  codigoNuevo &&
  cantidadNuevaMatch
) {
  estado = {
    active: false,
    phase: 'base',
    pendingField: '',
    draft: {
      cuenta_cliente: '',
      codigo_producto: '',
      cantidad: null,
      direccion_entrega: '',
      contacto: '',
      correo: '',
      telefono: ''
    },
    commercialApproved: false,
    lastCompleted: null,
    technicalContext: estado.technicalContext || null,
    lastProduct: estado.lastProduct || null
  };
  draft = estado.draft;
}

// -----------------------------------------------------------------------------
// EDICIÓN DE REVISIÓN COMERCIAL
// Permite volver a campos ya revisados sin perder el borrador.
// Ejemplos: "corregir pago", "cambiar entrega", "editar asesor".
// -----------------------------------------------------------------------------
if (estado.lastCompleted && typeof estado.lastCompleted === 'object') {
  const normalCorreccion = mensaje
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/\s+/g,' ').trim();

  const quiereCorregir = /\b(corregir|cambiar|editar|modificar|ajustar)\b/.test(normalCorreccion);

  if (quiereCorregir) {
    let campoCorreccion = '';

    if (/\b(pago|condicion(?:es)? de pago|credito|credito)\b/.test(normalCorreccion)) {
      campoCorreccion = 'pago';
    } else if (/\b(entrega|plazo|tiempo de entrega)\b/.test(normalCorreccion)) {
      campoCorreccion = 'entrega';
    } else if (/\b(correo|email)\b.*\basesor\b|\basesor\b.*\b(correo|email)\b/.test(normalCorreccion)) {
      campoCorreccion = 'asesor_email';
    } else if (/\b(telefono|tel)\b.*\basesor\b|\basesor\b.*\b(telefono|tel)\b/.test(normalCorreccion)) {
      campoCorreccion = 'asesor_telefono';
    } else if (/\b(asesor|vendedor)\b/.test(normalCorreccion)) {
      campoCorreccion = 'asesor_nombre';
    }

    if (campoCorreccion) {
      const d = estado.lastCompleted;
      const item = Array.isArray(d.items) && d.items.length ? d.items[0] : {};

      estado.phase = 'revision';
      estado.pendingField = campoCorreccion;
      estado.commercialApproved = false;
      estado.active = true;

      let preguntaCorreccion = '';
      if (campoCorreccion === 'pago') {
        preguntaCorreccion =
          '✏️ **Corrección de condiciones de pago**\n\n' +
          '**Pago actual:** ' + (limpiar(d.condiciones_pago) || 'Por confirmar') + '\n\n' +
          'Escribe la condición correcta. Si quieres conservar el valor original de CAF, escribe **Usar CAF**.';
      } else if (campoCorreccion === 'entrega') {
        preguntaCorreccion =
          '✏️ **Corrección de entrega**\n\n' +
          '**Entrega actual:** ' + (limpiar(item.tiempo_entrega) || 'Por confirmar') + '\n\n' +
          'Escribe el plazo correcto o **Usar CAF** para conservar el valor calculado.';
      } else if (campoCorreccion === 'asesor_nombre') {
        preguntaCorreccion =
          '✏️ **Corrección de asesor**\n\n' +
          '**Asesor actual:** ' + (limpiar(d.asesor) || 'Por asignar') + '\n\n' +
          'Escribe el nombre correcto del asesor.';
      } else if (campoCorreccion === 'asesor_telefono') {
        preguntaCorreccion =
          '✏️ **Corrección de teléfono del asesor**\n\n' +
          '**Teléfono actual:** ' + (limpiar(d.telefono_asesor) || 'Sin registrar') + '\n\n' +
          'Escribe el teléfono correcto.';
      } else if (campoCorreccion === 'asesor_email') {
        preguntaCorreccion =
          '✏️ **Corrección de correo del asesor**\n\n' +
          '**Correo actual:** ' + (limpiar(d.correo_asesor).replace(/\\@/g,'@') || 'Sin registrar') + '\n\n' +
          'Escribe el correo correcto.';
      }

      return [{
        json: salida({
          esCotizacion: true,
          generarDocumento: false,
          respuestaDirectaRevision: true,
          cotizacionCancelada: false,
          cotizacionLista: false,
          datosDocumento: d,
          mensajeCotizacion: preguntaCorreccion
        })
      }];
    }
  }
}

// -----------------------------------------------------------------------------
// REVISIÓN COMERCIAL PERSISTENTE
// -----------------------------------------------------------------------------
if (estado.phase === 'revision' && estado.pendingField && estado.lastCompleted) {
  const d = estado.lastCompleted;
  const item = Array.isArray(d.items) && d.items.length ? d.items[0] : {};
  const campo = estado.pendingField;
  let valido = true;
  let mensajeError = '';

  if (campo === 'pago') {
    if (/^(usar\s+(caf|cad|actual)|si|sí|correcto|esta bien|está bien|dejalo asi|déjalo así|igual|mantener)$/i.test(mensaje)) {
      const pagoCAF = limpiar(d.condiciones_pago_caf);
      if (pagoCAF && pagoCAF.toLowerCase() !== 'por confirmar') {
        d.condiciones_pago = pagoCAF;
      } else if (limpiar(d.condiciones_pago) && limpiar(d.condiciones_pago).toLowerCase() !== 'por confirmar') {
        // Conserva el valor actual cuando el borrador proviene de una versión anterior.
      } else {
        valido = false;
        mensajeError = 'CAF no tiene una condición de pago confirmada. ¿Cuál será la condición de pago?';
      }
    } else if (mensaje.length >= 3) {
      d.condiciones_pago = mensaje;
    } else {
      valido = false;
      mensajeError = '¿Cuál será la condición de pago?';
    }
  } else if (campo === 'entrega') {
    if (/^(usar\s+(caf|cad|actual)|si|sí|correcto|esta bien|está bien|dejalo asi|déjalo así|igual|mantener)$/i.test(mensaje)) {
      const actual = limpiar(item.tiempo_entrega);
      if (actual && !/confirmar/i.test(actual)) {
        // Conserva el plazo actual.
      } else {
        valido = false;
        mensajeError = 'El plazo actual todavía requiere confirmación. ¿Cuál será el plazo de entrega?';
      }
    } else if (mensaje.length >= 3) {
      item.tiempo_entrega = mensaje;
    } else {
      valido = false;
      mensajeError = 'Indícame el plazo de entrega final.';
    }
  } else if (campo === 'asesor_nombre') {
    if (mensaje.length >= 3) d.asesor = mensaje;
    else {
      valido = false;
      mensajeError = 'Indícame el nombre del asesor responsable.';
    }
  } else if (campo === 'asesor_telefono') {
    const tel = telefonoValido(mensaje);
    if (tel) d.telefono_asesor = tel;
    else {
      valido = false;
      mensajeError = 'Ese teléfono no parece válido. Revísalo y vuelve a enviarlo.';
    }
  } else if (campo === 'asesor_email') {
    const email = emailValido(mensaje);
    if (email) d.correo_asesor = email;
    else {
      valido = false;
      mensajeError = 'Ese correo no parece válido. Revísalo y vuelve a enviarlo.';
    }
  }

  if (Array.isArray(d.items) && d.items.length) d.items[0] = item;
  estado.lastCompleted = d;

  if (!valido) {
    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion: mensajeError
      })
    }];
  }

  const orden = ['pago', 'entrega', 'asesor_nombre', 'asesor_telefono', 'asesor_email'];
  const idx = orden.indexOf(campo);
  const siguiente = idx >= 0 && idx < orden.length - 1 ? orden[idx + 1] : '';

  if (siguiente) {
    estado.pendingField = siguiente;

    let pregunta = '';
    if (siguiente === 'pago') {
      const actual = limpiar(d.condiciones_pago) || 'Por confirmar';
      pregunta =
        `**Condiciones de pago actuales:** ${actual}\n\n` +
        '¿Las dejamos así o cuál será la condición final?';
    } else if (siguiente === 'entrega') {
      const actual = limpiar(item.tiempo_entrega) || 'Por confirmar';
      pregunta =
        '✅ Condiciones de pago registradas.\n\n' +
        `**Entrega actual:** ${actual}\n\n` +
        '¿La dejamos así o cuál será el plazo final?';
    } else if (siguiente === 'asesor_nombre') {
      pregunta = '✅ Plazo de entrega registrado.\n\n¿Cuál es el **nombre del asesor** responsable de esta cotización?';
    } else if (siguiente === 'asesor_telefono') {
      pregunta = 'Perfecto. Ahora indícame el **teléfono directo del asesor**.';
    } else if (siguiente === 'asesor_email') {
      pregunta = 'Gracias. Ahora indícame el **correo del asesor**.';
    }

    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        mensajeCotizacion: pregunta
      })
    }];
  }

  // Final de revisión comercial.
  d.estado = 'APROBADA_PARA_GENERAR';
  d.nota_control = 'REVISIÓN COMERCIAL COMPLETADA. Revisión final antes de envío al cliente.';
  estado.lastCompleted = d;
  estado.phase = 'aprobada';
  estado.pendingField = '';
  estado.commercialApproved = true;

  const resumen =
    '✅ **Revisión comercial completada.**\n\n' +
    '- Cotización: **se asignará automáticamente al generar el documento**\n' +

    `- Pago: ${limpiar(d.condiciones_pago)}\n` +
    `- Entrega: ${limpiar(d.items?.[0]?.tiempo_entrega)}\n` +
    `- Asesor: ${limpiar(d.asesor)}\n` +
    `- Teléfono asesor: ${limpiar(d.telefono_asesor)}\n` +
    `- Correo asesor: ${limpiar(d.correo_asesor)}\n\n` +
    'Si todo está correcto, escribe **Generar cotización** para crear Google Docs, PDF y Word.';

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      datosDocumento: d,
      mensajeCotizacion: resumen
    })
  }];
}

// Si el usuario pide generar/aprobar y ya existe un borrador, primero pasa por revisión comercial.
if (solicitaGenerarDocumento) {
  if (estado.lastCompleted && typeof estado.lastCompleted === 'object') {
    if (estado.commercialApproved === true && estado.phase === 'aprobada') {
      return [{
        json: salida({
          esCotizacion: true,
          generarDocumento: true,
          respuestaDirectaRevision: false,
          cotizacionCancelada: false,
          cotizacionLista: true,
          datosDocumento: estado.lastCompleted,
          mensajeCotizacion: ''
        })
      }];
    }

    estado.phase = 'revision';
    estado.pendingField = 'pago';
    estado.commercialApproved = false;

    const d = estado.lastCompleted;
    const item = Array.isArray(d.items) && d.items.length ? d.items[0] : {};
    d.iva_estado = 'Precio A CAF = precio final de venta al cliente; no agregar IVA adicional.';
    estado.lastCompleted = d;

    const valorPrecio = Number(item.precio_unitario_preliminar || 0);
    const precioSeguro = Number.isFinite(valorPrecio) ? valorPrecio : 0;
    const partesPrecio = precioSeguro.toFixed(2).split('.');
    partesPrecio[0] = partesPrecio[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    const precio = partesPrecio.join('.');
    const actual = limpiar(d.condiciones_pago) || 'Por confirmar';

    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: true,
        cotizacionCancelada: false,
        cotizacionLista: false,
        datosDocumento: d,
        mensajeCotizacion:
          '🔎 **Revisión comercial**\n\n' +
          `Precio unitario: **Q${precio}**\n` +
          `Condiciones de pago actuales: **${actual}**\n\n` +
          '¿Las dejamos así o cuál será la condición final?'
      })
    }];
  }

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      faltantes: ['borrador de cotización'],
      mensajeCotizacion:
        'Aún no tengo un borrador listo. Dime qué producto, cantidad y cliente deseas cotizar.'
    })
  }];
}

const iniciaCotizacion =
  /\b(cot[ií]z[a-záéíóúñ]*|presupuesto|proforma)\b/i.test(mensaje) ||
  /\b(quiero|necesito|deseo|puedes|podrias|podrías)\b.*\b(oferta|cot[ií]z)/i.test(mensaje);

const cancelar =
  estado.active &&
  /\b(cancelar|cancela|cancelémosla|cancelemosla|salir|detener)\b.*\b(cotiz|solicitud)?/i.test(mensaje);

const esCotizacion = Boolean(estado.active || iniciaCotizacion);

if (!esCotizacion) {
  return [{ json: salida({
    esCotizacion: false,
    generarDocumento: false,
    respuestaDirectaRevision: false,
    cotizacionCancelada: false,
    cotizacionLista: false
  }) }];
}

if (cancelar) {
  estado.active = false;
  estado.phase = 'base';
  estado.pendingField = '';
  estado.commercialApproved = false;
  estado.lastCompleted = null;
  estado.draft = {
    cuenta_cliente: '',
    codigo_producto: '',
    cantidad: null,
    direccion_entrega: '',
    contacto: '',
    correo: '',
    telefono: ''
  };

  return [{
    json: {
      ...input,
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: false,
      cotizacionCancelada: true,
      cotizacionLista: false,
      draft: estado.draft,
      mensajeCotizacion: 'De acuerdo. Cancelé el borrador de cotización que estábamos preparando.',
      sessionKeyCotizacion: sessionId,
      persist_session_id: sessionId,
      persist_state_json: JSON.stringify(estado)
    }
  }];
}

estado.active = true;

// Si estamos completando contacto, el mensaje actual responde al campo pendiente.
if (estado.phase === 'contacto' && estado.pendingField) {
  const campo = estado.pendingField;

  if (campo === 'contacto') {
    let valor = mensaje
      .replace(/^\s*a\s+nombre\s+de\s+/i, '')
      .replace(/^\s*nombre\s*:\s*/i, '')
      .trim();
    if (valor) draft.contacto = valor;
  } else if (campo === 'correo') {
    const email = emailValido(mensaje);
    if (email) draft.correo = email;
  } else if (campo === 'telefono') {
    const tel = telefonoValido(mensaje);
    if (tel) draft.telefono = tel;
  }

  const faltantesContacto = [];
  if (!draft.contacto) faltantesContacto.push('contacto');
  if (!draft.correo) faltantesContacto.push('correo');
  if (!draft.telefono) faltantesContacto.push('telefono');

  estado.draft = draft;

  if (faltantesContacto.length > 0) {
    estado.pendingField = faltantesContacto[0];

    let mensajeCotizacion = '';
    if (estado.pendingField === 'contacto') {
      mensajeCotizacion = '¿A nombre de quién debe dirigirse la cotización?';
    } else if (estado.pendingField === 'correo') {
      if (campo === 'contacto') {
        mensajeCotizacion = 'Perfecto. Ahora indícame el correo del contacto.';
      } else {
        mensajeCotizacion = 'Ese correo no parece válido. Revísalo y vuelve a enviarlo.';
      }
    } else {
      mensajeCotizacion = 'Gracias. Por último, indícame el teléfono del contacto.';
    }

    return [{
      json: salida({
        esCotizacion: true,
        generarDocumento: false,
        respuestaDirectaRevision: false,
        cotizacionCancelada: false,
        cotizacionLista: false,
        faltantes: faltantesContacto,
        mensajeCotizacion
      })
    }];
  }

  estado.phase = 'base';
  estado.pendingField = '';
  estado.draft = draft;

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: false,
      cotizacionCancelada: false,
      cotizacionLista: true,
      faltantes: [],
      mensajeCotizacion: ''
    })
  }];
}

// Cuenta CAF, por ejemplo AR-026.
const cuentaMatch = mensaje.toUpperCase().match(/\b[A-Z]{1,5}-\d{2,8}\b/);
if (cuentaMatch) {
  draft.cuenta_cliente = cuentaMatch[0];
}

// Si ya estamos preparando una cotización y acabamos de pedir cliente,
// acepta también el nombre comercial en vez de exigir la cuenta CAF.
if (
  cotizacionEstabaActiva &&
  estado.pendingField === 'cuenta_cliente' &&
  !draft.cuenta_cliente &&
  !cuentaMatch
) {
  const normalizaNombre = v => limpiar(v)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();

  const textoCliente = mensaje
    .replace(/^\s*(?:para|cliente|es|seria|sería|el cliente es|la empresa es)\s+/i,'')
    .trim();

  const ultimo = estado.lastClient || {};
  const ultimoNombre = normalizaNombre(ultimo.nombre || ultimo.nombre_cliente);
  const textoNormal = normalizaNombre(textoCliente);

  if (
    ultimo.cuenta &&
    ultimoNombre &&
    textoNormal &&
    (textoNormal.includes(ultimoNombre) || ultimoNombre.includes(textoNormal))
  ) {
    draft.cuenta_cliente = limpiar(ultimo.cuenta).toUpperCase();
  } else if (textoCliente.length >= 3) {
    resolverClientePorNombre = true;
    clienteBusqueda = textoCliente;
  }
}

// Si la cotización se inicia mencionando directamente el cliente por nombre,
// por ejemplo: "Quiero cotizar este producto para Ingenio Magdalena",
// resuelve el nombre en CAF sin volver a preguntar "¿para qué cliente?".
if (
  iniciaCotizacion &&
  !draft.cuenta_cliente &&
  !cuentaMatch &&
  !resolverClientePorNombre
) {
  const clienteInicial = mensaje.match(
    /\bpara\s+(?:(?:el|la)\s+)?(?:cliente|empresa)?\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑ0-9&.,'()\- ]{2,}?)(?=\s+(?:cantidad|cant\.?|por\s+\d+|\d+(?:[.,]\d+)?\s*(?:unidades?|uds?|piezas?))\b|[.!?]?\s*$)/i
  );

  if (clienteInicial && clienteInicial[1]) {
    const candidato = clienteInicial[1]
      .replace(/[,.!?]+$/g, '')
      .replace(/\s+/g, ' ')
      .trim();

    const generico = /^(este|esta|el|la|un|una|cliente|empresa|producto|servicio)$/i.test(candidato);

    if (!generico && candidato.length >= 3) {
      resolverClientePorNombre = true;
      clienteBusqueda = candidato;
    }
  }
}

// Código de producto, excluyendo la cuenta CAF.
const candidatosCodigo = mensaje.toUpperCase().match(/\b(?=[A-Z0-9-]*[A-Z])(?=[A-Z0-9-]*\d)[A-Z0-9-]{5,}\b/g) || [];
const codigoProducto = candidatosCodigo.find(x => x !== draft.cuenta_cliente && !/^[A-Z]{1,5}-\d{2,8}$/.test(x));
if (codigoProducto) draft.codigo_producto = codigoProducto;

// Si el usuario inicia una cotización después de consultar un producto,
// reutiliza ese contexto en vez de volver a pedir el código.
if (iniciaCotizacion && !draft.codigo_producto) {
  const aprobado = limpiar(estado.technicalContext?.approvedCode).toUpperCase();
  const reciente = limpiar(estado.lastProduct?.codigo).toUpperCase();
  if (aprobado) draft.codigo_producto = aprobado;
  else if (reciente) draft.codigo_producto = reciente;
}

// Cantidad.
let cantidad = null;
const patronesCantidad = [
  /(?:quiero\s+cotizar|necesito\s+cotizar|cotizar|cantidad(?:\s+de)?|cant(?:idad)?|necesito|quiero)\s*:?\s*(\d+(?:[.,]\d+)?)/i,
  /\b(\d+(?:[.,]\d+)?)\s*(?:unidades?|uds?|piezas?)\b/i
];
for (const patron of patronesCantidad) {
  const m = mensaje.match(patron);
  if (m) {
    cantidad = Number(m[1].replace(',', '.'));
    break;
  }
}
if (cantidad === null && estado.active && !draft.cantidad && /^\s*\d+(?:[.,]\d+)?\s*$/.test(mensaje)) {
  cantidad = Number(mensaje.replace(',', '.'));
}
if (Number.isFinite(cantidad) && cantidad > 0) draft.cantidad = cantidad;

// Dirección de entrega opcional.
const entrega = mensaje.match(/(?:direcci[oó]n\s+de\s+entrega|entrega)\s*:\s*(.+)$/i);
if (entrega && entrega[1]) draft.direccion_entrega = entrega[1].trim();

// -----------------------------------------------------------------------------
// CONTROL TÉCNICO ANTES DEL BORRADOR
// Aplica únicamente cuando el código proviene del último cruce técnico de la sesión.
// -----------------------------------------------------------------------------
const ctxTecnico = estado.technicalContext;
const candidatosTecnicos = Array.isArray(ctxTecnico?.candidatos) ? ctxTecnico.candidatos : [];
const codigoDraft = limpiar(draft.codigo_producto).toUpperCase();
const vieneDeCruceTecnico = Boolean(
  codigoDraft &&
  candidatosTecnicos.some(c => limpiar(c.codigo).toUpperCase() === codigoDraft)
);

if (
  vieneDeCruceTecnico &&
  (!ctxTecnico.approved || limpiar(ctxTecnico.approvedCode).toUpperCase() !== codigoDraft)
) {
  estado.draft = draft;

  return [{
    json: salida({
      esCotizacion: true,
      generarDocumento: false,
      respuestaDirectaRevision: true,
      cotizacionCancelada: false,
      cotizacionLista: false,
      faltantes: ['validación técnica'],
      mensajeCotizacion:
        '⚠️ **Cotización detenida por control técnico.**\n\n' +
        'El código **' + codigoDraft + '** proviene de una búsqueda técnica y todavía no tiene una aprobación técnica registrada en esta sesión.\n\n' +
        'Un responsable técnico debe confirmar con: **Aprobar técnicamente ' + codigoDraft + ' por Nombre del responsable técnico**.\n\n' +
        'Después de esa aprobación podremos continuar con el borrador de cotización.'
    })
  }];
}

estado.draft = draft;

const faltantes = [];
if (!draft.cuenta_cliente) faltantes.push('cuenta CAF del cliente');
if (!draft.codigo_producto) faltantes.push('código del producto');
if (!draft.cantidad) faltantes.push('cantidad');

const cotizacionLista = faltantes.length === 0;

let mensajeCotizacion = '';
if (!cotizacionLista) {
  const siguiente = faltantes[0];

  if (siguiente === 'cuenta CAF del cliente') {
    estado.pendingField = 'cuenta_cliente';
    mensajeCotizacion = draft.codigo_producto
      ? 'Claro. Tomaré el código **' + draft.codigo_producto + '** que ya tenemos en contexto. ¿Para qué cliente deseas preparar la cotización? Puedes escribir el nombre o la cuenta CAF.'
      : 'Claro. ¿Para qué cliente deseas preparar la cotización? Puedes escribir el nombre o la cuenta CAF.';
  } else if (siguiente === 'código del producto') {
    estado.pendingField = 'codigo_producto';
    mensajeCotizacion = 'Perfecto. ¿Qué código de producto deseas cotizar?';
  } else {
    estado.pendingField = 'cantidad';
    mensajeCotizacion = 'Perfecto. ¿Cuántas unidades deseas cotizar?';
  }
} else {
  estado.pendingField = '';
}

estado.draft = draft;

return [{
  json: salida({
    esCotizacion: true,
    generarDocumento: false,
    respuestaDirectaRevision: false,
    cotizacionCancelada: false,
    cotizacionLista,
    faltantes,
    resolverClientePorNombre,
    clienteBusqueda,
    mensajeCotizacion
  })
}];

const gestion = $('Cotización - Gestionar borrador').item.json;
const draft = gestion.draft || {};
const clienteResp = $('CAF - Cotización consultar cliente').item.json || {};
const productoResp = $('CAF - Cotización consultar producto').item.json || {};
const existenciaResp = $('CAF - Cotización consultar existencia').item.json || {};

const c = clienteResp.cliente || {};
const p = productoResp.prod || {};
const existencias = Array.isArray(existenciaResp.v_existencia) ? existenciaResp.v_existencia : [];

const limpio = v => (v ?? '').toString().trim();
const num = v => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

const clienteValido = Boolean(clienteResp.success && limpio(c.cuenta));
const productoValido = Boolean(productoResp.success && limpio(p.codpro));

const sessionId = gestion.sessionKeyCotizacion || 'sesion-default';

let estado = {};
try {
  estado = JSON.parse(gestion.persist_state_json || '{}');
} catch (e) {}
if (!estado || typeof estado !== 'object') estado = {};

const salidaPersistente = (extra = {}) => ({
  ...extra,
  persist_session_id: sessionId,
  persist_state_json: JSON.stringify(estado)
});

if (!clienteValido || !productoValido) {
  const problemas = [];
  if (!clienteValido) problemas.push('No pude validar la cuenta del cliente en CAF Web.');
  if (!productoValido) problemas.push('No pude validar el producto en CAF Web.');

  estado.active = true;
  estado.phase = 'base';
  estado.pendingField = '';
  estado.draft = draft;

  return [{
    json: salidaPersistente({
      listoDocumento: false,
      estado: 'ERROR_VALIDACION_CAF',
      mensaje: problemas.join('\n') + '\n\nEl borrador de cotización sigue guardado. Puedes corregir la cuenta o el código e intentarlo nuevamente.',
      draft
    })
  }];
}

const contactoCAF = limpio(c.contacto);
const correoCAF = [...new Set(
  limpio(c.email)
    .replace(/\\@/g, '@')
    .split(',')
    .map(x => x.trim().replace(/\\@/g, '@'))
    .filter(Boolean)
)].join(', ');
const telefonoCAF = limpio(c.telefono);

const contactoFinal = limpio(draft.contacto) || contactoCAF;
const correoFinal = limpio(draft.correo) || correoCAF;
const telefonoFinal = limpio(draft.telefono) || telefonoCAF;

const faltantesContacto = [];
if (!contactoFinal) faltantesContacto.push('contacto');
if (!correoFinal) faltantesContacto.push('correo');
if (!telefonoFinal) faltantesContacto.push('telefono');

if (faltantesContacto.length > 0) {
  estado.active = true;
  estado.phase = 'contacto';
  estado.pendingField = faltantesContacto[0];
  estado.draft = {
    ...draft,
    contacto: contactoFinal,
    correo: correoFinal,
    telefono: telefonoFinal
  };

  let pregunta = '';
  if (estado.pendingField === 'contacto') {
    pregunta = '¿A nombre de quién debe dirigirse la cotización?';
  } else if (estado.pendingField === 'correo') {
    pregunta = '¿Cuál es el correo del contacto?';
  } else {
    pregunta = '¿Cuál es el teléfono del contacto?';
  }

  return [{
    json: salidaPersistente({
      listoDocumento: false,
      estado: 'FALTAN_DATOS_CONTACTO',
      mensaje:
        '✅ Ya validé el cliente y el producto en CAF Web.\n\n' +
        'Antes de preparar el documento necesito completar los datos de contacto que no están registrados en CAF.\n\n' +
        pregunta,
      draft: estado.draft
    })
  }];
}

const cantidad = num(draft.cantidad);
