const resp = $json || {};
  const limpio = v => (v ?? "").toString().trim();

  let registros = [];
  const arrays = [resp.prod, resp.productos, resp.data, resp.rows, resp.results, resp.items];
  for (const a of arrays) {
    if (Array.isArray(a)) {
      registros = a;
      break;
    }
  }
  if (!registros.length) {
    for (const v of Object.values(resp)) {
      if (Array.isArray(v) && v.length && typeof v[0] === "object") {
        registros = v;
        break;
      }
    }
  }

  const tecnico = $("Producto - Interpretar análisis técnico").item.json.analisisTecnico || {};
  const originales = limpio($("Chat - Entrada").item.json.chatInput);
  const busqueda = limpio(tecnico.consulta_caf || $("IA - Preparar búsqueda producto").item.json.text);

  const normaliza = s => limpio(s)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, " ")
    .trim();

  const q = normaliza(busqueda);
  const original = normaliza(originales);
  const tokens = q.split(/\s+/).filter(t => t.length >= 2);

  const familias = [
    ["BOLA", ["BOLA", "BALL", "ESFERA"]],
    ["MARIPOSA", ["MARIPOSA", "BUTTERFLY"]],
    ["COMPUERTA", ["COMPUERTA", "GATE"]],
    ["GLOBO", ["GLOBO", "GLOBE"]],
    ["RETENCION", ["RETENCION", "CHECK", "NO RETORNO"]],
    ["AGUJA", ["AGUJA", "NEEDLE"]],
    ["REGULADORA", ["REGULADORA", "REGULADOR", "PRV"]],
    ["SEGURIDAD", ["SEGURIDAD", "SAFETY"]],
    ["TRAMPA", ["TRAMPA", "TRAP"]],
    ["MANOMETRO", ["MANOMETRO", "PRESSURE GAUGE"]]
  ];

  let familiaSolicitada = null;
  for (const [nombre, sinonimos] of familias) {
    if (sinonimos.some(s => q.includes(s) || original.includes(s))) {
      familiaSolicitada = { nombre, sinonimos };
      break;
    }
  }

  let conexionSolicitada = null;
  if (/\bROSCAD[AO]\b|\bROSCA\b|\bNPT\b|\bBSP\b|\bSCREWED\b|\bTHREADED\b/.test(q + " " + original)) {
    conexionSolicitada = { nombre: "ROSCADA", sinonimos: ["ROSCAD", "ROSCA", "NPT", "BSP", "SCREWED", "THREADED"] };
  } else if (/\bBRID[AO]\b|\bBRIDA\b|\bFLANGE\b|\bFLANCHAD[AO]\b/.test(q + " " + original)) {
    conexionSolicitada = { nombre: "BRIDA", sinonimos: ["BRIDA", "BRID", "FLANGE", "FLANCH"] };
  }

  const servicioVapor = /\bVAPOR\b|\bSTEAM\b/.test(q + " " + original);
  const sizeMatch = original.match(/\b(\d+(?:\s+\d+\/\d+|\/\d+)?)\s*(?:PULGADAS?|PULG|")/);
  const tamanoSolicitado = sizeMatch ? sizeMatch[1].replace(/\s+/g, " ") : limpio(tecnico.diametro);

  const fabricanteSolicitado = normaliza(tecnico.fabricante);
  const serieSolicitada = normaliza(tecnico.serie).replace(/^SERIE\s+/, "");

  const textoRegistro = r => normaliza([
    r.nombre_prod, r.descripcion, r.descrip, r.codpro,
    r.codigo_fabricante, r.categoria, r.marca
  ].filter(Boolean).join(" "));

  const escRegex = s => s.replace(/[.*+?^$()|[\]\\]/g, "\\$&");

  const contieneTamano = (texto, tamano) => {
    if (!tamano) return false;
    const esc = escRegex(tamano);
    const re = new RegExp("(^|[^0-9/])" + esc + '\\s*(?:"|PULG|NPT|BSP|BRIDA|FLANGE|$)');
    return re.test(texto);
  };

  const serieCoincide = (texto, serie) => {
    if (!serie) return true;
    const esc = escRegex(serie);
    return new RegExp("\\b(?:SERIE\\s*)?" + esc + "\\b").test(texto);
  };

  const evalua = r => {
    const texto = textoRegistro(r);
    let score = 0;
    let familiaOk = !familiaSolicitada;
    let conexionOk = !conexionSolicitada;
    let tamanoOk = !tamanoSolicitado;
    let fabricanteOk = !fabricanteSolicitado;
    let serieOk = !serieSolicitada;

    if (familiaSolicitada) {
      familiaOk = familiaSolicitada.sinonimos.some(s => texto.includes(s));
      if (familiaOk) score += 15;
    }
    if (conexionSolicitada) {
      conexionOk = conexionSolicitada.sinonimos.some(s => texto.includes(s));
      if (conexionOk) score += 8;
    }
    if (tamanoSolicitado) {
      tamanoOk = contieneTamano(texto, tamanoSolicitado);
      if (tamanoOk) score += 12;
    }
    if (fabricanteSolicitado) {
      fabricanteOk = texto.includes(fabricanteSolicitado);
      if (fabricanteOk) score += 10;
    }
    if (serieSolicitada) {
      serieOk = serieCoincide(texto, serieSolicitada);
      if (serieOk) score += 14;
    }

    if (servicioVapor && (texto.includes("VAPOR") || texto.includes("STEAM"))) score += 2;
    for (const t of tokens) {
      if (/^\d+$/.test(t)) continue;
      if (texto.includes(t)) score += 1;
    }

    return {
      ...r,
      __texto: texto,
      __score: score,
      __familiaOk: familiaOk,
      __conexionOk: conexionOk,
      __tamanoOk: tamanoOk,
      __fabricanteOk: fabricanteOk,
      __serieOk: serieOk
    };
  };

  let candidatos = registros.map(evalua).sort((a,b) => b.__score - a.__score);

  if (familiaSolicitada) {
    const x = candidatos.filter(r => r.__familiaOk);
    if (x.length) candidatos = x;
  }
  if (conexionSolicitada) {
    const x = candidatos.filter(r => r.__conexionOk);
    if (x.length) candidatos = x;
  }
  if (tamanoSolicitado) {
    const x = candidatos.filter(r => r.__tamanoOk);
    if (x.length) candidatos = x;
  }
  if (fabricanteSolicitado) {
    const x = candidatos.filter(r => r.__fabricanteOk);
    if (x.length) candidatos = x;
  }
  if (serieSolicitada) {
    const x = candidatos.filter(r => r.__serieOk);
    if (x.length) candidatos = x;
  }

  candidatos = candidatos.slice(0, 6);

  if (!candidatos.length) {
    return [{
      json: {
        encontrados: false,
        analisisTecnico: tecnico,
        mensaje:
          "La Base Técnica orientó la búsqueda, pero no encontré en CAF una coincidencia comercial suficientemente segura para esa configuración.\n\n" +
          "**Conclusión técnica:** " + limpio(tecnico.nota_tecnica) + "\n\n" +
          "No voy a forzar una relación con un código CAF. Se requiere validación técnica/comercial antes de cotizar."
      }
    }];
  }

  return [{
    json: {
      encontrados: true,
      solicitudOriginal: originales,
      analisisTecnico: tecnico,
      candidatos
    }
  }];

