const raw = (($json.output ?? $json.text ?? "") + "").trim();
  const preliminar = (($("IA - Preparar búsqueda producto").item.json.text ?? "") + "").trim();
  const original = (($("Chat - Entrada").item.json.chatInput ?? "") + "").trim();

  let parsed = {};
  try {
    const ini = raw.indexOf("{");
    const fin = raw.lastIndexOf("}");
    if (ini >= 0 && fin > ini) parsed = JSON.parse(raw.slice(ini, fin + 1));
  } catch (e) {
    parsed = {};
  }

  const limpio = v => (v ?? "").toString().trim();
  const consulta = limpio(parsed.consulta_caf) || preliminar || original;

  const tokens = consulta
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .split(/\s+/)
    .filter(Boolean);

  const terminoCAF =
    tokens.find(t => ["VALVULA","TRAMPA","MANOMETRO","ACTUADOR","REGULADOR","AISLAMIENTO"].includes(t)) ||
    tokens.find(t => t.length >= 4 && !/^\d/.test(t)) ||
    tokens.find(t => t.length >= 3) ||
    consulta;

  return [{
    json: {
      solicitudOriginal: original,
      busquedaPreliminar: preliminar,
      analisisTecnicoRaw: raw,
      analisisTecnico: {
        base_tecnica_consultada: parsed.base_tecnica_consultada === true,
        fabricante: limpio(parsed.fabricante),
        familia: limpio(parsed.familia),
        serie: limpio(parsed.serie),
        conexion: limpio(parsed.conexion),
        diametro: limpio(parsed.diametro),
        servicio: limpio(parsed.servicio),
        presion_psi: parsed.presion_psi ?? null,
        temperatura_c: parsed.temperatura_c ?? null,
        configuracion: limpio(parsed.configuracion) || "SIN_EVIDENCIA",
        servicio_validado: limpio(parsed.servicio_validado) || "PENDIENTE",
        consulta_caf: consulta,
        nota_tecnica: limpio(parsed.nota_tecnica) || "La Base Técnica no devolvió una conclusión estructurada suficiente; CAF se consultará solo como búsqueda comercial.",
        fuentes: Array.isArray(parsed.fuentes) ? parsed.fuentes : []
      },
      consultaCAF: consulta,
      terminoCAF
    }
  }];

const base = $json || {};
