const respuestas = $input.all();
const candidatos = $("Producto - Expandir candidatos CAF").all().map(x => x.json);
const limpio = v => (v ?? "").toString().trim();
const tecnico = $("Producto - Preparar candidatos").first().json.analisisTecnico || {};

const formatoDinero = (valor) => {
  const n = Number(valor || 0);
  if (!Number.isFinite(n) || n <= 0) return "No registrado";
  const partes = n.toFixed(2).split(".");
  const entero = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return "Q" + entero + "." + partes[1];
};

const formatoCantidad = (valor) => {
  const n = Number(valor || 0);
  if (!Number.isFinite(n)) return "0";
  const max2 = Math.round(n * 100) / 100;
  const partes = max2.toString().split(".");
  const entero = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return partes.length > 1 ? entero + "." + partes[1] : entero;
};

const lineas = candidatos.map((c, i) => {
  const resp = respuestas[i]?.json || {};
  const regs = Array.isArray(resp.v_existencia) ? resp.v_existencia : [];
  const totalCAF = regs.reduce((s, r) => s + Number(r.existencia || 0), 0);

  let existenciaTxt = "";
