    existenciaTxt = formatoCantidad(totalCAF) + " unidades disponibles";
  } else if (totalCAF < 0) {
    existenciaTxt = "Sin disponibilidad inmediata (saldo CAF: " + formatoCantidad(totalCAF) + ")";
