    existenciaTxt = "Sin disponibilidad inmediata";
  }

  return (
    (i + 1) + ". **" + (c.descripcion || "Producto sin descripción") + "**\n" +
    "   Código CAF: " + (c.codigo || "No disponible") + "\n" +
