  configuracion: limpio(tecnico.configuracion) || 'SIN_EVIDENCIA',
  servicio_validado: limpio(tecnico.servicio_validado) || 'PENDIENTE',
  nota_tecnica: limpio(tecnico.nota_tecnica),
  fuentes: Array.isArray(tecnico.fuentes) ? tecnico.fuentes : [],
  candidatos: candidatosGuardados,
  approved: false,
  approvedCode: '',
  approvedBy: '',
  approvedAt: ''
};

return [{
  json: {
    mensaje: $('Producto - Resumir cruce técnico CAF').first().json.mensaje,
    persist_session_id: sessionId,
    persist_state_json: JSON.stringify(estado),
    technicalContext: estado.technicalContext
  }
}];

const gestionBase = $('Cotización - Gestionar borrador').item.json || {};
const gestion = JSON.parse(JSON.stringify(gestionBase));
const d = gestion.datosDocumento || {};

const limpio = v => (v ?? '').toString().trim();

const ahoraGT = new Date();
const year = Number(new Intl.DateTimeFormat('en-US', {
  year: 'numeric',
  timeZone: 'America/Guatemala'
}).format(ahoraGT));

const existente = limpio(d.cotizacion);
let counter = { year, last: 0 };

try {
  const row = $input.first().json || {};
  if (row.state_json) {
    const parsed = JSON.parse(row.state_json);
    if (parsed && typeof parsed === 'object') {
      counter.year = Number(parsed.year || year);
      counter.last = Number(parsed.last || 0);
    }
  }
} catch (e) {}

if (counter.year !== year) {
  counter = { year, last: 0 };
}

let numero = existente;
let reutilizado = /^IA-\d{4}-\d{4,}$/.test(numero);

if (!reutilizado) {
  counter.last += 1;
  numero = 'IA-' + year + '-' + String(counter.last).padStart(4, '0');
}

d.cotizacion = numero;
gestion.datosDocumento = d;

// Actualiza también el estado persistente de la sesión para que el mismo número
// se reutilice si el usuario vuelve a pulsar "Generar cotización".
let estado = {};
try {
  estado = JSON.parse(gestion.persist_state_json || '{}');
} catch (e) {}
if (!estado || typeof estado !== 'object') estado = {};
if (!estado.lastCompleted || typeof estado.lastCompleted !== 'object') {
  estado.lastCompleted = d;
} else {
  estado.lastCompleted.cotizacion = numero;
}
estado.assignedQuoteNumber = numero;
estado.assignedQuoteAt = new Date().toISOString();

gestion.persist_state_json = JSON.stringify(estado);

return [{
  json: {
    ...gestion,
    numeroCotizacion: numero,
    consecutivo_reutilizado: reutilizado,
    counter_session_id: '__PRAISA_COTIZADOR_CONSECUTIVO__',
    counter_state_json: JSON.stringify(counter)
  }
}];

const raw = (($('Chat - Entrada').item.json.chatInput || '') + '').toLowerCase();
const normal = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const stop = new Set([
  'necesito','quiero','deseo','busco','buscar','buscando','consultar','consulta','informacion','info',
  'producto','productos','descripcion','tecnica','tecnico','por','favor','un','una','el','la','los','las',
  'de','del','para','que','me','puedes','podrias','cotizar','cotizacion'
]);

const tokens = normal
  .replace(/[^a-z0-9"'.\/-]+/g,' ')
  .split(/\s+/)
  .filter(Boolean)
  .filter(t => !stop.has(t));

const tieneDatoTecnico =
  /\b\d+(?:[.,]\d+)?\s*(?:psi|bar|°?c|c|pulgadas?|in|mm|v|vac|vdc)\b/i.test(raw) ||
  /\b(npt|bsp|flange|flanged|roscada|roscado|socket|soldable|vapor|agua|aire|inoxidable|carbon|acero|ptfe|rptfe|delval|forbes|parker|ashcroft)\b/i.test(normal);

const tieneTipoProducto =
  /\b(valvula|válvula|manometro|manómetro|actuador|trampa|solenoide|sensor|transmisor|termometro|termómetro|aislamiento|fibra|empaque|kit|reparacion|reparación|regulador|filtro|bomba|medidor|switch|controlador)\b/i.test(raw);

return [{json:{
  descripcionSuficiente: tokens.length >= 1 && (tieneDatoTecnico || tieneTipoProducto),
  terminosUtiles: tokens
}}];

const input = $('Configuración CAF').item.json || {};
const sessionId = (input.sessionId || input.session_id || input.webhookId || 'sesion-default').toString();

let estado = {};
try {
  const row = $('Memoria - Leer sesión').item.json || {};
  if (row.state_json) estado = JSON.parse(row.state_json);
} catch (e) {}
if (!estado || typeof estado !== 'object') estado = {};

const p = $('CAF - Consultar producto').item.json.prod || {};
const ex = $('CAF - Consultar existencia del producto').item.json || {};
const registros = Array.isArray(ex.v_existencia) ? ex.v_existencia : [];
const limpio = v => (v ?? '').toString().trim();
const num = v => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

estado.lastProduct = {
  codigo: limpio(p.codpro),
  descripcion: limpio(p.nombre_prod),
  precio_a: num(p.precioa),
  existencia_total: registros.reduce((s,r)=>s+num(r.existencia),0),
  updatedAt: new Date().toISOString()
};

return [{json:{
  persist_session_id: sessionId,
  persist_state_json: JSON.stringify(estado)
}}];

const raw = (($('Cotización - Gestionar borrador').item.json.clienteBusquedaGeneral || $('Chat - Entrada').item.json.chatInput || '') + '').trim();
const sinAcentos = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const normal = sinAcentos(raw).toLowerCase().replace(/\s+/g,' ').trim();

const generico =
  /^(quiero|necesito|deseo|quisiera|puedes|podrias)?\s*(informacion|datos|consultar|consulta|buscar|busqueda)?\s*(de|del|sobre)?\s*(un|una|el|la)?\s*cliente\s*$/i.test(normal) ||
  /^(cliente|informacion de cliente|datos de cliente)$/i.test(normal);

let termino = raw
  .replace(/^\s*(?:quiero|necesito|deseo|quisiera)?\s*(?:informaci[oó]n|datos|consultar|consulta|buscar|b[uú]squeda)?\s*(?:de|del|sobre)?\s*(?:un|una|el|la)?\s*cliente\s*(?:llamado|nombre)?\s*[:\-]?\s*/i,'')
  .replace(/^\s*(?:para|sobre|de)\s+/i,'')
  .trim();

if (generico || termino.length < 3) termino = '';

return [{json:{
  buscarPorNombre: Boolean(termino),
  terminoCliente: termino
}}];

const resp = $input.first().json || {};
const query = ($('Cliente - Preparar búsqueda por nombre').item.json.terminoCliente || '').toString().trim();
const normaliza = v => (v ?? '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const limpio = v => (v ?? '').toString().trim();

let registros = [];
for (const key of ['cliente','clientes','data','rows','records']) {
  if (Array.isArray(resp[key])) { registros = resp[key]; break; }
}
if (!registros.length) {
  const arr = Object.values(resp).find(v => Array.isArray(v));
  if (arr) registros = arr;
}

const q = normaliza(query);
const qTokens = q.split(' ').filter(t => t.length > 1);

const score = r => {
  const nombre = normaliza(r.nombre_cliente || r.cliente || r.nombre);
  const cuenta = normaliza(r.cuenta || r.codigo || r.codcliente);
  if (!nombre && !cuenta) return 0;
  if (cuenta === q) return 120;
  if (nombre === q) return 110;
  let s = 0;
  if (nombre.startsWith(q)) s = Math.max(s, 95);
  if (nombre.includes(q)) s = Math.max(s, 88);
  const hits = qTokens.filter(t => nombre.includes(t)).length;
  if (qTokens.length && hits === qTokens.length) s = Math.max(s, 78 + Math.min(10,qTokens.length));
  else if (hits) s = Math.max(s, Math.round(55 * hits / qTokens.length));
  return s;
};

const candidatos = registros
  .map(r => ({r,score:score(r)}))
  .filter(x => x.score >= 45)
  .sort((a,b)=>b.score-a.score)
  .slice(0,8);

const top = candidatos[0];
const second = candidatos[1];
const seleccionUnica = Boolean(
  top &&
  top.score >= 78 &&
  (!second || top.score >= second.score + 8 || normaliza(top.r.nombre_cliente) === q)
);

const elegido = seleccionUnica ? top.r : null;
const lista = candidatos.slice(0,5).map(x => ({
  cuenta: limpio(x.r.cuenta || x.r.codigo || x.r.codcliente),
  nombre_cliente: limpio(x.r.nombre_cliente || x.r.cliente || x.r.nombre),
  nit: limpio(x.r.nit),
  ciudad: limpio(x.r.ciudad),
  direccion: limpio(x.r.direccion),
  telefono: limpio(x.r.telefono),
  contacto: limpio(x.r.contacto),
  email: limpio(x.r.email),
  score: x.score
}));

return [{json:{
  consulta: query,
  encontrado: Boolean(top),
  seleccionado: seleccionUnica,
  cliente: elegido ? {
    cuenta: limpio(elegido.cuenta || elegido.codigo || elegido.codcliente),
    nombre_cliente: limpio(elegido.nombre_cliente || elegido.cliente || elegido.nombre),
    nit: limpio(elegido.nit),
    ciudad: limpio(elegido.ciudad),
    direccion: limpio(elegido.direccion),
    telefono: limpio(elegido.telefono),
    contacto: limpio(elegido.contacto),
    email: limpio(elegido.email)
  } : null,
  candidatos: lista
}}];

const r = $('Cliente - Resolver búsqueda por nombre').item.json || {};
const c = r.cliente || {};
const limpio = v => (v ?? '').toString().trim();
const limpiarCorreo = v => limpio(v).replace(/\\@/g, '@');

let estado = {};
try {
  const row = $('Memoria - Leer sesión').first().json || {};
  if (row.state_json) estado = JSON.parse(row.state_json);
} catch(e) {}
if (!estado || typeof estado !== 'object') estado = {};
estado.pendingLookup = '';

estado.lastClient = {
  cuenta: limpio(c.cuenta),
  nombre: limpio(c.nombre_cliente),
  nit: limpio(c.nit),
  ciudad: limpio(c.ciudad),
  updatedAt: new Date().toISOString()
};

const faltantes=[];
if(!limpio(c.telefono)) faltantes.push('Teléfono');
if(!limpio(c.contacto)) faltantes.push('Contacto');
if(!limpiarCorreo(c.email)) faltantes.push('Correo');

let mensaje =
  'Información consultada directamente en CAF Web:\n\n' +
  '🔹 Cuenta: ' + (limpio(c.cuenta) || 'No registrada') + '\n' +
  '🔹 Cliente: ' + (limpio(c.nombre_cliente) || 'No registrado') + '\n' +
  '🔹 NIT: ' + (limpio(c.nit) || 'No registrado') + '\n' +
  '🔹 Dirección: ' + (limpio(c.direccion) || 'No registrada') + '\n' +
  '🔹 Ciudad: ' + (limpio(c.ciudad) || 'No registrada') + '\n' +
  '🔹 Teléfono: ' + (limpio(c.telefono) || 'No registrado') + '\n' +
  '🔹 Contacto: ' + (limpio(c.contacto) || 'No registrado') + '\n' +
  '🔹 Correo: ' + (limpiarCorreo(c.email) || 'No registrado');

if(faltantes.length){
  mensaje += '\n\n⚠️ Información pendiente de completar:\n' + faltantes.map(x=>'• '+x).join('\n');
}

return [{json:{
  output: mensaje,
  persist_session_id: ($('Configuración CAF').item.json.sessionId || 'sesion-default').toString(),
  persist_state_json: JSON.stringify(estado)
}}];

