const r = $('Cotización - Resolver cliente por nombre').item.json || {};
const c = r.cliente || {};
const base = $('Cotización - Gestionar borrador').item.json || {};
let estado = {};
try { estado = JSON.parse(base.persist_state_json || '{}'); } catch(e) {}
if (!estado || typeof estado !== 'object') estado = {};
if (!estado.draft || typeof estado.draft !== 'object') estado.draft = {};
const limpio=v=>(v??'').toString().trim();

estado.draft.cuenta_cliente = limpio(c.cuenta).toUpperCase();
estado.lastClient = {
  cuenta: limpio(c.cuenta).toUpperCase(),
  nombre: limpio(c.nombre_cliente),
  nit: limpio(c.nit),
  ciudad: limpio(c.ciudad),
  updatedAt: new Date().toISOString()
};

const faltantes=[];
if(!estado.draft.codigo_producto) faltantes.push('código del producto');
if(!estado.draft.cantidad) faltantes.push('cantidad');

if(faltantes[0]==='código del producto') estado.pendingField='codigo_producto';
else if(faltantes[0]==='cantidad') estado.pendingField='cantidad';
else estado.pendingField='';

let mensaje =
  'Encontré **' + (limpio(c.nombre_cliente) || 'el cliente') + '** en CAF' +
  (limpio(c.cuenta) ? ' (cuenta **' + limpio(c.cuenta).toUpperCase() + '**)' : '') + '. La usaré para esta cotización.';

if(faltantes[0]==='código del producto') mensaje += '\n\n¿Qué código de producto deseas cotizar?';
else if(faltantes[0]==='cantidad') mensaje += '\n\n¿Cuántas unidades deseas cotizar?';
else mensaje += '\n\nYa tengo cliente, producto y cantidad. Escribe **continuar cotización** para validar los datos en CAF.';

return [{json:{
  output: mensaje,
  persist_session_id: base.persist_session_id,
  persist_state_json: JSON.stringify(estado)
}}];

